function todayStr(){const t=new Date();return `${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,'0')}-${String(t.getDate()).padStart(2,'0')}`;}
function fmtDate(iso){const[y,m,d]=iso.split('-');const days=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];return `${days[new Date(+y,+m-1,+d).getDay()]} ${d}/${m}`;}
function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}

