  "2026-09-21": {"videos": [["Reforço nos Tópicos com Pior Desempenho – FGV Concurso", "https://www.youtube.com/results?search_query=refor%C3%A7o+t%C3%B3picos+pior+desempenho+FGV+concurso", "YouTube"]], "reading": [["Material do tópico fraco identificado no simulado 1", "https://www.isaca.org/resources/cobit", "ISACA"]], "questions": [["Questões focadas no pior tópico do simulado – QConcursos FGV", "https://www.qconcursos.com/questoes-de-concursos/questoes?examining_board_ids=7", "Resolver 25q no tópico de pior desempenho do simulado 1"], ["Questões reforço específico – PCI Concursos", "https://www.pciconcursos.com.br/questoes/?banca=FGV", "Buscar: tópico específico identificado no simulado"]], "tips": ["<strong>Reforço pós-simulado:</strong> não estude de tudo — concentre nas lacunas reais identificadas no simulado 1.", "<strong>Crie cartões de memória:</strong> para conceitos que errou no simulado, escreva frente (conceito) e verso (definição). Revise nos dias seguintes."]},
  "2026-09-22": {"videos": [["LGPD + LAI – Questões FGV Comentadas", "https://www.youtube.com/results?search_query=LGPD+LAI+quest%C3%B5es+FGV+comentadas", "YouTube"]], "reading": [["LGPD – Art. 7, 11, 41, 52 – releitura dos artigos-chave", "https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm", "Planalto"]], "questions": [["Questões LGPD + LAI FGV – QConcursos", "https://www.qconcursos.com/questoes-de-concursos/questoes?q=LGPD+LAI&examining_board_ids=7", "Resolver 20q LGPD + 10q LAI FGV – sem consulta"], ["Questões Legislação Digital FGV – PCI Concursos", "https://www.pciconcursos.com.br/questoes/lgpd/?banca=FGV", "Resolver questões de LGPD + Marco Civil FGV"]], "tips": ["<strong>LGPD × LAI:</strong> LGPD protege dados pessoais; LAI garante acesso a informações públicas. Podem coexistir — lei específica prevalece.", "<strong>Art. 52 LGPD:</strong> sanções em ordem crescente — advertência → multa simples → multa diária → publicização → bloqueio → eliminação → suspensão."]},
  "2026-09-23": {"videos": [["FGV Específico TI – Tópicos Mais Cobrados Questões Comentadas", "https://www.youtube.com/results?search_query=FGV+espec%C3%ADfico+TI+t%C3%B3picos+mais+cobrados+quest%C3%B5es+comentadas", "YouTube"]], "reading": [["FGV Analista TI – Distribuição de Questões por Tópico (análise)", "https://www.qconcursos.com/questoes-de-concursos/provas?examining_board_ids=7", "QConcursos"]], "questions": [["Questões Específico TI FGV mais cobrados – QConcursos", "https://www.qconcursos.com/questoes-de-concursos/questoes?discipline_ids=56&examining_board_ids=7", "Resolver 30q nos tópicos mais frequentes FGV TI"], ["Questões TI FGV recentes – PCI Concursos", "https://www.pciconcursos.com.br/questoes/tecnologia-da-informacao/?banca=FGV", "Buscar: banco de dados redes segurança engenharia software FGV"]], "tips": ["<strong>FGV TI mais cobrados:</strong> Banco de Dados (SQL, modelagem), Redes (TCP/IP, camadas), Segurança (criptografia, autenticação), Engenharia de Software (ciclos, padrões).", "<strong>Priorize questões recentes:</strong> provas dos últimos 3 anos da FGV têm maior probabilidade de refletir o estilo atual da banca."]},
  "2026-09-24": {"videos": [["Como Fazer Flashcards para Concursos – Método Eficiente", "https://www.youtube.com/results?search_query=como+fazer+flashcards+concurso+m%C3%A9todo+eficiente", "YouTube"]], "reading": [["Revisão de anotações e mapas mentais das semanas 1-8", "https://www.pciconcursos.com.br/questoes/?banca=FGV", "Material pessoal — revisar caderno/notas"]], "questions": [["Questões mistas de revisão – QConcursos FGV", "https://www.qconcursos.com/questoes-de-concursos/questoes?examining_board_ids=7", "Resolver 20q aleatórias FGV como revisão geral"], ["Flashcard de questões – PCI Concursos", "https://www.pciconcursos.com.br/questoes/?banca=FGV", "Revisar 30 questões antigas anotadas como dúvida"]], "tips": ["<strong>Revisão ativa:</strong> ao revisar anotações, feche o caderno e tente reescrever os pontos de memória — é mais eficiente que reler passivamente.", "<strong>Flashcards FGV:</strong> crie cards para definições exatas (LGPD, ITIL, COBIT) que a FGV cobra literalmente — banca gosta de transcrição fiel."]},
