  "2026-09-26": {"videos": [["Revisão Simulado 2 – Análise de Desempenho e Erros", "https://www.youtube.com/results?search_query=revis%C3%A3o+simulado+2+an%C3%A1lise+desempenho+erros+concurso", "YouTube"]], "reading": [["Gabarito e resolução do simulado 2 – material de referência", "https://www.qconcursos.com/questoes-de-concursos/questoes?examining_board_ids=7", "QConcursos"]], "questions": [["Refazer erros do simulado 2 – QConcursos FGV", "https://www.qconcursos.com/questoes-de-concursos/questoes?examining_board_ids=7", "Refazer todos os erros + comparar com simulado 1"], ["Questões extras tópicos fracos simulado 2 – PCI Concursos", "https://www.pciconcursos.com.br/questoes/?banca=FGV", "Resolver 15q extras nos tópicos com baixo acerto"]], "tips": ["<strong>Comparação de simulados:</strong> se um tópico continuou com baixo acerto nos dois simulados, precisa de revisão profunda imediata.", "<strong>Tendência de melhora:</strong> a maioria deve ter melhorado — se houve piora em algum tópico, avalie se não está ocorrendo 'esquecimento por falta de revisão'."]},
